283         uint256 timeDiff = block.timestamp - investment.lastClaimTime;
284         uint256 dailyReward = (investment.amount * plan.dailyReturn) / 10000; // Convert basis points
285         uint256 rewardAmount = (dailyReward * timeDiff) / 1 days;
286         
287         // Rewards accrue indefinitely until capital is withdrawn.
288         // The lock period only gatekeeps capital withdrawal, not reward accrual.
289         // Therefore, the capping logic previously here is removed.
290         
291         return rewardAmount;
292     }
