696     /**
697      * @dev Internal function to get users at a specific network level
698      * @param _user Address of the user whose network to analyze
699      * @param _level Level to get users for
700      * @return usersAtLevel Array of user addresses at the specified level
701      */
702     function _getUsersAtLevel(address _user, uint256 _level) internal view returns (address[] memory) {
703         if (_level == 0) {
704             return users[_user].directReferrals;
705         }
706         
707         // For levels > 0, we need to recursively find users
708         address[] memory previousLevel = _getUsersAtLevel(_user, _level - 1);
709         uint256 totalCount = 0;
710         
711         // First, count total users at this level
712         for (uint256 i = 0; i < previousLevel.length; i++) {
713             totalCount += users[previousLevel[i]].directReferrals.length;
714         }
715         
716         // Create array and populate it
717         address[] memory usersAtLevel = new address[](totalCount);
718         uint256 currentIndex = 0;
719         
720         for (uint256 i = 0; i < previousLevel.length; i++) {
721             address[] memory directRefs = users[previousLevel[i]].directReferrals;
722             for (uint256 j = 0; j < directRefs.length; j++) {
723                 usersAtLevel[currentIndex] = directRefs[j];
724                 currentIndex++;
725             }
726         }
727         
728         return usersAtLevel;
729     }
